self.KB_CONTENT["card:778696"]={"id":"card:778696","ty":"card","sourceId":"778696","title":"『批次生產計劃維護-依開工日』中的『需領用量 (TB007)』為何？","ver":"GP4以上","topic":"庫存","keywords":["庫存","生產","產品","計劃"],"y":"other","answer":"* 相依需求數量，此為產品結構的用量資料值。* [F2]各庫庫存查詢。* 需領用量會隨著相依的生產數量的修改，而自動重新計算。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
