self.KB_CONTENT["card:777510"]={"id":"card:777510","ty":"card","sourceId":"777510","title":"『託外進貨單建立作業』中的『.進貨包裝數量 (TI016)』為何？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單","大於","包裝","等於"],"y":"other","answer":"* 進貨包裝數量必須大於等於零。* 驗收包裝數量不可大於進貨包裝數量。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
