self.KB_CONTENT["field:749933"]={"id":"field:749933","ty":"field","sourceId":"749933","title":"選擇FAX/Email傳送狀態","ver":"iGP","topic":"","keywords":[],"job":"付款單憑證","code":"","answer":"* 若未購買『FAX/Email處理系統』(FEP)，需隱藏。* 計Y.已傳送、N.未傳送及全部。","file":"fields.jsonl"};
